{
  "similarities": [
    {
      "point": "Both identify Helsingia as a province of Sweden.",
      "quote_britannica": "HELSINGIA, a province of Sweden,",
      "quote_wikipedia": "Hälsingland (Swedish pronunciation:), sometimes referred to by the Latin name Helsingia, is a historical province or landskap in central Sweden."
    },
    {
      "point": "Both state that the province borders the Gulf of Bothnia.",
      "quote_britannica": "bounded by the Botnhic gulph on the cafl,",
      "quote_wikipedia": "It borders Gästrikland, Dalarna, Härjedalen, Medelpad and the Gulf of Bothnia."
    },
    {
      "point": "Both state that the province borders Dalarna.",
      "quote_britannica": "and by Dalecarila on the well.",
      "quote_wikipedia": "It borders Gästrikland, Dalarna, Härjedalen, Medelpad and the Gulf of Bothnia."
    }
  ],
  "differences": [
    {
      "point": "Britannica gives only two borders, while Wikipedia lists five bordering provinces and the gulf.",
      "quote_britannica": "bounded by the Botnhic gulph on the cafl, and by Dalecarila on the well.",
      "quote_wikipedia": "It borders Gästrikland, Dalarna, Härjedalen, Medelpad and the Gulf of Bothnia."
    },
    {
      "point": "Britannica describes it as a current province, while Wikipedia calls it a historical province with no administrative purpose.",
      "quote_britannica": "HELSINGIA, a province of Sweden, bounded by the Botnhic gulph on the cafl,",
      "quote_wikipedia": "Hälsingland (Swedish pronunciation:), sometimes referred to by the Latin name Helsingia, is a historical province or landskap in central Sweden."
    }
  ],
  "claims": [
    {
      "claim": "Helsingia is a province of Sweden.",
      "tag": "enduring",
      "quote_britannica": "HELSINGIA, a province of Sweden,",
      "quote_wikipedia": "Hälsingland (Swedish pronunciation:), sometimes referred to by the Latin name Helsingia, is a historical province or landskap in central Sweden."
    },
    {
      "claim": "Helsingia is bounded by the Botnian Gulf on the east.",
      "tag": "enduring",
      "quote_britannica": "bounded by the Botnhic gulph on the cafl,",
      "quote_wikipedia": "It borders Gästrikland, Dalarna, Härjedalen, Medelpad and the Gulf of Bothnia."
    },
    {
      "claim": "Helsingia is bounded by Dalecarlia on the west.",
      "tag": "enduring",
      "quote_britannica": "and by Dalecarila on the well.",
      "quote_wikipedia": "It borders Gästrikland, Dalarna, Härjedalen, Medelpad and the Gulf of Bothnia."
    }
  ],
  "term_pairs": [
    {
      "old": "Botnhic gulph",
      "new": "Gulf of Bothnia",
      "quote_britannica": "bounded by the Botnhic gulph on the cafl,",
      "quote_wikipedia": "It borders Gästrikland, Dalarna, Härjedalen, Medelpad and the Gulf of Bothnia."
    },
    {
      "old": "Dalecarila",
      "new": "Dalarna",
      "quote_britannica": "and by Dalecarila on the well.",
      "quote_wikipedia": "It borders Gästrikland, Dalarna, Härjedalen, Medelpad and the Gulf of Bothnia."
    }
  ],
  "wiki_only_topics": [
    {
      "topic": "Administrative status and counties",
      "quote_wikipedia": "The traditional provinces of Sweden serve no administrative or political purpose, but are historical and cultural entities. In the case of Hälsingland the province constitutes the northern part of the län ('administrative county ') Gävleborg County."
    },
    {
      "topic": "Municipalities and settlements",
      "quote_wikipedia": "The following municipalities have their seats in Hälsingland:\n\nBollnäs\n\nHudiksvall\n\nLjusdal\n\nNordanstig\n\nOvanåker\n\nSöderhamn"
    },
    {
      "topic": "Coat of arms and heraldry",
      "quote_wikipedia": "The coat of arms were granted in 1560 in the era of King Gustav Vasa. At that time, Hälsingland was known for its large scale goat breeding, and the arms depicted a standing goat facing heraldic right (blazon: Sable, a Goat rampant Or attired and hoofed Gules)."
    },
    {
      "topic": "Geography, terrain, and geology",
      "quote_wikipedia": "The terrain is mostly hilly and rocky, sloping down towards the coast. The highest elevation in the northern part is 530 meters, and 671 meters in the western part. Approximately 85% of the land area is covered with forest, and the timber industry has historically been the main source of income."
    },
    {
      "topic": "History and earliest mentions",
      "quote_wikipedia": "The earliest mention of the people of Hälsingland may be in the Old English poem Widsith, from the 9th or 10th century, where a people called the Hælsings are referred to. The first definite mention of the people is made by Adam of Bremen around 1070, in reference to the leidang shipping fleet."
    }
  ]
}
